def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = max(counts, key=counts.get)
    marker = next(v for v in counts if v != background)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    out = [row[:] for row in grid]

    # Close the horizontal edges at the top and bottom of the marker pattern.
    for r in (top, bottom):
        for c in range(left, right + 1):
            if grid[r][c] == background:
                out[r][c] = 2

    # Complete repeated vertical strokes (three or more marker points).
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if len(rows) >= 3:
            for r in range(rows[0], rows[-1] + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

